// Score weights: leaving the visible map or hiding under UI costs most, then covering another
// label or station, then crossing the route. Switching sides must win by HYSTERESIS to happen.
const OFFSCREEN = 8, COVERED = 8, CROWDED = 5, DOT = 900, ROUTE = 60, PREFERENCE = 12, HYSTERESIS = 150

const overlap = (a: Rect, b: Rect) =>
  Math.max(0, Math.min(a.right, b.right) - Math.max(a.left, b.left)) * Math.max(0, Math.min(a.bottom, b.bottom) - Math.max(a.top, b.top))

/** Whether segment a-b passes through the rectangle (Liang-Barsky clipping). */
function crosses(a: Point, b: Point, r: Rect): boolean {
  let t0 = 0, t1 = 1
  const dx = b[0] - a[0], dy = b[1] - a[1]
  const edges: Point[] = [[-dx, a[0] - r.left], [dx, r.right - a[0]], [-dy, a[1] - r.top], [dy, r.bottom - a[1]]]
  for (const [p, q] of edges) {
    if (p === 0) { if (q < 0) return false; continue }
    const t = q / p
    if (p < 0) { if (t > t1) return false; t0 = Math.max(t0, t) }
    else { if (t < t0) return false; t1 = Math.min(t1, t) }
  }
  return true
}

